#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto do_op=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np(n);
        int idx=0;
        for(int i=n-y;i<n;i++) np[idx++]=p[i];
        for(int i=x;i<n-y;i++) np[idx++]=p[i];
        for(int i=0;i<x;i++) np[idx++]=p[i];
        p=np;
    };
    for(int k=0;k<n-1;k++){
        int pos=-1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;
        // Try all single operations
        bool found=false;
        for(int x=1;x<n&&!found;x++) for(int y=1;x+y<n&&!found;y++){
            // Check if element at pos goes to k
            int npos;
            if(pos>=n-y) npos=pos-(n-y);
            else if(pos>=x) npos=pos-x+y;
            else npos=n-x+pos;
            if(npos==k){
                // Also check elements [0..k-1] stay in place
                bool ok=true;
                for(int i=0;i<k&&ok;i++){
                    int ni;
                    if(i>=n-y) ni=i-(n-y);
                    else if(i>=x) ni=i-x+y;
                    else ni=n-x+i;
                    if(ni!=i) ok=false;
                }
                if(ok){do_op(x,y);found=true;}
            }
        }
        if(!found){
            // Move to pos n-1 first with op(pos,1) if valid
            if(pos>0 && pos+1<n){do_op(pos,n-1-pos);} // element goes to n-1-pos+... recalc
            for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
            if(pos!=k) for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){int npos;if(pos>=n-y)npos=pos-(n-y);else if(pos>=x)npos=pos-x+y;else npos=n-x+pos;bool ok=npos==k;for(int i=0;i<k&&ok;i++){int ni;if(i>=n-y)ni=i-(n-y);else if(i>=x)ni=i-x+y;else ni=n-x+i;if(ni!=i)ok=false;}if(ok){do_op(x,y);break;}}
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
